ns.AddQuests("c_ROGUE", {
    { id = 96779, name = "Syndicate Sabotage", level = 24, minLevel = 24, classes = 8, giver = "Myrokos Silentform", start = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, finish = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, steps = { { name = "Lord Tomas", area = 267, x = 79.2, y = 45.7 } }, objective = "Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform.", desc = "Sometimes, <race>, a single cut in the right place will drop a foe dead. The same is often true of organizations.\n\nOur agents have identified a key target among the ranks of the Syndicate: a man by the name of Lord Tomas.\n\nHe plays an instrumental role in the functions of Durnholde Keep, in Hillsbrad Foothills. If you wish to be of service to Ravenholdt, go to Durnholde and eliminate him. The quicker, and quieter, the better." },
    { id = 96781, name = "What's the Big Idea?", level = 36, minLevel = 24, classes = 8, giver = "Myrokos Silentform", start = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, finish = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, objective = "Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor.", desc = "We have noticed a Syndicate scouting party prowling around the ruins of Alterac, led by a man named Barton.\n\nThey're clearly searching for something, but I cannot know what without reading his scouting reports.\n\nI ask that you pickpocket the report from him, rather than killing him outright. Barton's death will tip off the Syndicate that we're on to them, and they will certainly take counter-measures to cover their tracks.\n\nIf you hope to find him, he is most likely among the Syndicate at Strahnbrad." },
    { id = 96782, name = "Covert Extraction", level = 36, minLevel = 24, requires = { 96781 }, classes = 8, finish = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, objective = "Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform.", desc = "It seems our friend Barton here has made this very easy for us. He is after two heirlooms of the Perenolde family within the ruins of Alterac. The Blade of House Perenolde, a sword, and the Royal Aegis of Perenolde, a shield.\n\nFrom the report, it seems these armaments are within two towers among the ruins. Best we acquire them before the Syndicate does.\n\nThe ogres occupying the ruins are fierce, but I trust you should be able to sneak past them without needing to bloody your blade at all." },
    { id = 96783, name = "A Way In", level = 34, minLevel = 24, classes = 8, giver = "Myrokos Silentform", start = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, finish = { npc = "Syndicate Footlocker", area = 45, x = 32.2, y = 26.4 }, desc = "Stromgarde Keep is one of the Syndicate's largest strongholds. Many of the organization's most important dealings take place behind its walls.\n\nI have received word of a certain trade taking place between members of the Syndicate somewhere in Arathi Highlands, and I'm certain the details of this trade can be found somewhere in Stromgarde.\n\nTo infiltrate the keep without arousing suspicion, you'll need a disguise. See if you can find one among the Syndicate outside the keep, at Northfold Manor." },
    { id = 96784, name = "Master of Disguise", level = 34, minLevel = 24, faction = "Horde", classes = 8, giver = "Syndicate Footlocker", start = { npc = "Syndicate Footlocker", area = 45, x = 32.2, y = 26.4 }, finish = { npc = "Anastasia Miller", area = 45, x = 26.8, y = 64.6 }, objective = "While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.\n\nProvided item:", desc = "<You recall Myrokos' instructions to find out about an important deal going on with the Syndicate in Stromgarde Keep. With your disguise, you should be able to talk to members of the Syndicate somewhat freely. Surely, one of them knows something.>" },
    { id = 96785, name = "Ain't No Telling", level = 34, minLevel = 24, classes = 8, finish = { npc = "Anastasia Miller", area = 45, x = 26.8, y = 64.6 }, objective = "Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", desc = "Who do you think you are? Showing up and sticking your nose in official business.\n\nI'm not telling some rookie anything about the higher-up's dealings without good reason. Unless you've got something important, or valuable, for me, I've got nothing to say to you." },
    { id = 96786, name = "The Syndicate Sting", level = 34, minLevel = 24, classes = 8, finish = { npc = "Myrokos Silentform", area = 36, x = 85, y = 80.4 }, objective = "Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", desc = "Falconcrest sent some guys to do a handoff at the southern part of Thoradin's wall. I don't know what they're picking up. Must be good, because everyone involved has kept it a total secret. I don't think the guys picking it up even know what it is.\n\nThat's all I've got. Don't make me regret telling you that." },
})

ns.AddQuests("c_SHAMAN", {
    { id = 94789, name = "Call of Air", level = 30, minLevel = 30, faction = "Alliance", classes = 64, giver = "Eldrun Stormbreaker", start = { npc = "Eldrun Stormbreaker", area = 1537, x = 47.4, y = 13.6 }, finish = { npc = "Veyric Thunderhame", area = 45, x = 59.8, y = 27.6 }, desc = "The winds o' Azeroth greet ye, and soon ye'll stand among some o' our mightiest kin. I'm proud to see how far ye've come--your future looks bright indeed.\n\nThe element o' air's a tricky one to master, but I've faith your skill will see ye through any challenge.\n\nMake your way north into Arathi Highlands. In its northern hills, you'll find Veyric Thundervein. He'll teach ye more." },
    { id = 96016, name = "The Tempest's Weapons", level = 40, minLevel = 30, requires = { 96135 }, faction = "Alliance", classes = 64, finish = { npc = "Bath'rah the Windwatcher", area = 36, x = 80.4, y = 66.8 }, objective = "Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", desc = "Ye did good, and I can see yer itchin' fer yer reward. Sorry tae say, I'm not exactly a dwarf of many possessions.\n\n<Veyric gestures broadly at his remote location.>\n\nTell ye what, though. I hear a troll named the Windwatcher lives out in the Alterac Mountains. He's a powerful shaman himself, and an expert in storm elementals. If ye bring that there elemental core to him, I bet he can make ye a weapon worthy of yer victory." },
    { id = 96135, name = "Heed My Call", level = 40, minLevel = 30, requires = { 79358 }, faction = "Alliance", classes = 64, giver = "Veyric Thunderhame", start = { npc = "Veyric Thunderhame", area = 45, x = 59.8, y = 27.6 }, finish = { npc = "Veyric Thunderhame", area = 45, x = 59.8, y = 27.6 }, steps = { { name = "Eye of the Tempest", area = 400, x = 36.5, y = 39.8 } }, objective = "Use the Twisted Totems to put an end to the quilboar ritual.", desc = "Euck, just bein' around these blasted totems is givin' me the willies--but that's good. This much twisted corruption will be exactly what we need tae summon the quilboar's elementals.\n\nGo to the Thousand Needles and find a suitable spot for your defenses. The steam pools should work. They're rich with fire, earth, water, and air alike. Place these totems and be ready for a fight. The Razormane won't take too kindly to yer interference." },
    { id = 96136, name = "Call of Air", level = 35, minLevel = 30, faction = "Horde", objective = "Find Prate Cloudseer in Thousand Needles.", desc = "As you have no doubt experienced yourself, the elements of Azeroth are unique to those in Zephras. It is one thing to channel the forces of nature within the elemental plains, and another thing entirely to do it down here in the muck.\n\nI could grant you your totem of air, but I think it would do you more good to meet with the one who trains the other earth-bound initiates. What say you, <name>?" },
    { id = 96264, name = "Elemental Aid", level = 33, minLevel = 30, requires = { 94789 }, faction = "Alliance", classes = 64, giver = "Veyric Thunderhame", start = { npc = "Veyric Thunderhame", area = 45, x = 59.8, y = 27.6 }, finish = { npc = "Veyric Thunderhame", area = 45, x = 59.8, y = 27.6 }, objective = "Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans.", desc = "So yer a big shot shaman now, eh? Ye've mastered the elements and want tae put 'em to good use? I think I got just the thing.\n\nIf ye want the elements' respect, ye gotta repay yer debts to 'em. They help you, you help them. And right now they need all the help they can get from those who would abuse their power.\n\nEarth's rumblin', <name>. It speaks of the quilboar amassin' for some ritual of terrible power. We need tae go investigate their kraul and see what they're up to. Bring me back whatever ye find." },
})

