    { id = 96607, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Horde", giver = "Eleanor Shackleton", start = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, finish = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, objective = "Sit near Eleanor's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96608, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, objective = "Sit near Eric's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96626, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Tomas", area = 12, x = 44.2, y = 66 }, objective = "Speak with Tomas in Goldshire to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96627, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", giver = "Marshal McBride", start = { npc = "Marshal McBride", area = 12, x = 48.8, y = 41.6 }, finish = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, desc = "<name>, you have proven your competence as a protector thus far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Goldshire. Go and see what he's doing." },
    { id = 96628, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", giver = "Mountaineer Thalos", start = { npc = "Mountaineer Thalos", area = 1, x = 33.4, y = 71.8 }, finish = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, objective = "Deliver the Supply Bundle to Eric Brighthammer near Kharanos.", desc = "Wait, <name>. I have another ask of you, before you brave that tunnel.\n\nMy mountaineers have reported an adventurer that's shown up just outside of Kharanos. Could you deliver these supplies to him?" },
    { id = 96629, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Gremlock Pilsnor", area = 1, x = 47.6, y = 52.4 }, objective = "Speak with Gremlock Pilsnor in Kharanos to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96630, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", finish = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, objective = "Bring the journal to Lyreena Duskblade near Dolanaar.", desc = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>" },
    { id = 96634, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Zarrin", area = 141, x = 57, y = 61.2 }, objective = "Speak with Zarrin in Dolanaar to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96638, name = "The Adventurer", level = 6, minLevel = 4, giver = "Aetheen of the Gales", start = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, finish = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, desc = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\n\nSeek him out and see what you can learn from him that may help you in your own travels." },
    { id = 96646, name = "Camping 101: Cooking", level = 6, minLevel = 4, giver = "Raan Wildwind", start = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, finish = { npc = "Zerril Softbreeze", area = 16593, x = 43.8, y = 43.8 }, objective = "Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96652, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", finish = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, objective = "Bring the journal to Brakk near Razor Hill.", desc = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>" },
    { id = 96655, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Cook Torka", area = 14, x = 51.2, y = 42.4 }, objective = "Speak with Cook Torka in Razor Hill to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96656, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", giver = "Executor Arren", start = { npc = "Executor Arren", area = 85, x = 32, y = 66 }, finish = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, desc = "<name>, you have proven yourself trustworthy in your endeavors against the Scarlet Crusade so far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Brill. Go and see what she's doing." },
    { id = 96658, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Eleanor Shackleton", start = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, finish = { npc = "William Pickman", area = 85, x = 61.8, y = 51.4 }, objective = "Speak with William Pickman in Brill to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96659, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", giver = "Chief Hawkwind", start = { npc = "Chief Hawkwind", area = 215, x = 43.9, y = 76.6 }, finish = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, objective = "Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", desc = "Wait, <name>. I have another ask of you, before you leave us.\n\nThere is an adventurer by the name of Kaga Wildhoof who has made camp just outside of Bloodhoof Village. She has greatly helped me in the past, and now I see my chance to repay her. Could you deliver these supplies to her?" },
    { id = 96661, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Pyall Silentstride", area = 215, x = 44.9, y = 61.6 }, objective = "Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
