    { id = 94004, name = "Craftsman's Writ: Elixir of Ogre's Strength", level = 60, minLevel = 1, finish = { npc = "Sos'mol", area = 36, x = 38.4, y = 61.2 }, objective = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", desc = "<Penned in faded ink, the note is requesting $2oa Elixir of Ogre's Strength, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>" },
